input.command:
playwright-cli -s=wb-react run-code 2>&1 '
const exampleBtn = page.getByRole("button", { name: "示例文本" });
const statBtn = page.getByRole("button", { name: "统 计" });
const clearBtn = page.getByRole("button", { name: "清 空" });

// Step 1: click 示例文本 + 统计
await exampleBtn.click();
await statBtn.click();

// Step 2: assert .result contains 字符数：9 and 单词数：4
const result = page.locator(".result");
await result.waitFor();
const resultText = await result.innerText();
if (!resultText.includes("字符数：9")) throw Error("断言失败: .result 未包含 字符数：9，实际: " + resultText);
if (!resultText.includes("单词数：4")) throw Error("断言失败: .result 未包含 单词数：4，实际: " + resultText);

// Step 3: fill pure whitespace, click stat, assert 单词数：0
const textarea = page.locator("textarea");
await textarea.fill("   ");
await statBtn.click();
const resultText2 = await result.innerText();
if (!resultText2.includes("单词数：0")) throw Error("断言失败: .result 未包含 单词数：0，实际: " + resultText2);

// Step 4: click clear, assert textarea empty and result count = 0
await clearBtn.click();
const inputValue = await textarea.inputValue();
if (inputValue.length !== 0) throw Error("断言失败: 清空后 textarea 不为空，实际: '" + inputValue + "'");
const resultText3 = await result.innerText();
if (!resultText3.includes("字符数：0")) throw Error("断言失败: 清空后字符数不为0，实际: " + resultText3);
if (!resultText3.includes("单词数：0")) throw Error("断言失败: 清空后单词数不为0，实际: " + resultText3);

return "WB_REACT_UI_ASSERTIONS_PASS";
' 2>&1

